    { r: 5, id: 'rum5', drop: 'u_r5', title: 'How Often Are We Paid Late?', ask: 'Of all invoices paid in full, what percent were paid after their due_date? One number, rounded to 1 decimal.', ret: 'pct_late', sql: 'SELECT ROUND(100.0 * SUM(CASE WHEN paid_date > due_date THEN 1 ELSE 0 END) / COUNT(*), 1) FROM invoices WHERE paid_date IS NOT NULL' },
    { r: 6, id: 'rum6', drop: 'u_r6', title: 'Second Only to One', ask: 'The second most expensive item in the whole ledger.', ret: 'name, unit_price', sql: 'SELECT name, unit_price FROM items WHERE unit_price = (SELECT MAX(unit_price) FROM items WHERE unit_price < (SELECT MAX(unit_price) FROM items))' },
    { r: 7, id: 'rum7', drop: 'u_r7', title: 'The Longest Silence', ask: 'What is the longest gap, in days, between one order_date and the next in the whole order book? One number.', ret: 'days', sql: 'WITH g AS (SELECT julianday(order_date) - julianday(LAG(order_date) OVER (ORDER BY order_date, order_id)) AS gap FROM orders) SELECT MAX(gap) FROM g' },
    { r: 8, id: 'rum8', drop: 'u_r8', title: 'Champion of Each Region', ask: 'For each customer region, the single customer with the highest Shipped revenue.', ret: 'region, name, revenue', sql: `WITH r AS (SELECT c.region, c.name, SUM(${LT}) AS revenue FROM customers c JOIN orders o ON o.customer_id = c.customer_id JOIN order_lines ol ON ol.order_id = o.order_id WHERE o.status = 'Shipped' GROUP BY c.customer_id, c.region, c.name), k AS (SELECT r.*, ROW_NUMBER() OVER (PARTITION BY region ORDER BY revenue DESC) AS rn FROM r) SELECT region, name, revenue FROM k WHERE rn = 1` }
